// Cognition Layer Phase 4 — bounded BFS retriever.
//
// Algorithm:
//   1. Tokenise the task into keywords (identifier-shaped substrings).
//   2. Score each symbol by keyword overlap, file-name overlap, and a
//      tiny visibility boost for `public` symbols.
//   3. Take the top K symbols as seeds, where K = max_files * 2.
//   4. BFS the (imports + reverseImports) graph from the seed files,
//      breadth `hop_depth`, capped at `max_files` total files.
//   5. Sort results deterministically and return.
//
// Determinism: every set / map iteration is sorted, ties resolve to the
// earliest-appearing file. The retriever is pure given a fixed index.

import type { IndexedRepo } from "./semantic_index";
import type { SemanticSlice, RepoFilter } from "./types";

const STOPWORDS = new Set([
  "a", "an", "the", "and", "or", "of", "to", "for", "with", "in", "on", "by", "is", "are", "was", "be", "as", "at", "it", "its", "this", "that", "these", "those",
  "i", "you", "we", "they", "my", "our", "your",
  "do", "does", "did", "can", "could", "should", "would", "will", "may", "might",
  "function", "class", "file", "code",
]);

function tokenise(s: string): string[] {
  const tokens = s.toLowerCase().match(/[a-z0-9_]{2,}/g) || [];
  return tokens.filter(t => !STOPWORDS.has(t));
}

/** Camel/snake split for symbol matching: parseFooBar → [parse, foo, bar]. */
function splitIdent(name: string): string[] {
  const parts: string[] = [];
  for (const seg of name.split(/[._]/)) {
    let acc = "";
    for (let i = 0; i < seg.length; i++) {
      const c = seg[i];
      const next = seg[i + 1];
      acc += c.toLowerCase();
      if ((c.toLowerCase() !== c && next && next.toLowerCase() === next) || i === seg.length - 1) {
        if (acc.length >= 2) parts.push(acc);
        acc = "";
      }
    }
  }
  return parts;
}

function scoreSymbol(symbolName: string, file: string, kw: Set<string>, visibility: string): number {
  let s = 0;
  for (const part of splitIdent(symbolName)) {
    if (kw.has(part)) s += 3;
  }
  for (const part of file.toLowerCase().split(/[\\/_.]/g)) {
    if (part.length >= 2 && kw.has(part)) s += 1;
  }
  if (visibility === "public") s += 0.25;
  return s;
}

export function walkIndex(index: IndexedRepo, task: string, hopDepth: number, maxFiles: number, repo_filter?: RepoFilter): SemanticSlice {
  const kw = new Set(tokenise(task));

  // Phase 10: build the set of allowed repo_ids. null/undefined means
  // 'no filter — every repo is fair game'. A non-empty filter restricts
  // both the seeding pass AND the BFS expansion so cross-repo edges
  // (which shouldn't exist for separately-cloned repos anyway) can't
  // pull files in by accident.
  const repoSet: Set<string> | null =
    repo_filter == null
      ? null
      : new Set(typeof repo_filter === "string" ? [repo_filter] : repo_filter);
  const fileAllowed = (file: string): boolean => {
    if (!repoSet) return true;
    const syms = index.symbolsByFile.get(file);
    if (!syms || syms.length === 0) {
      // No symbols means no repo_id evidence; permit (the file is on
      // disk for a reason — fall back to the file's recorded summary).
      const fs = index.fileSummaries.get(file);
      return fs ? repoSet.has(fs.repo_id) : true;
    }
    // The repo_id is uniform across symbols of one file (set by buildIndex).
    return repoSet.has(syms[0].repo_id);
  };

  // 1+2: score every symbol — skip files outside the repo filter.
  type Scored = { score: number; file: string; symbol: string; line: number };
  const scored: Scored[] = [];
  const sortedFiles = [...index.symbolsByFile.keys()].sort();
  for (const file of sortedFiles) {
    if (!fileAllowed(file)) continue;
    for (const sym of index.symbolsByFile.get(file)!) {
      const s = scoreSymbol(sym.name, file, kw, sym.visibility);
      if (s > 0) scored.push({ score: s, file, symbol: sym.name, line: sym.line });
    }
  }
  // Stable sort: highest score first, ties by file then by line.
  scored.sort((a, b) => b.score - a.score || a.file.localeCompare(b.file) || a.line - b.line);

  // 3: seed files.
  const K = Math.max(1, maxFiles * 2);
  const seedSymbols = scored.slice(0, K);
  const seedFiles: string[] = [];
  for (const s of seedSymbols) {
    if (!seedFiles.includes(s.file)) seedFiles.push(s.file);
  }

  // 4: BFS over imports + reverseImports up to hopDepth — also filtered.
  const visited = new Set<string>(seedFiles);
  let frontier: string[] = [...seedFiles];
  for (let depth = 0; depth < hopDepth && visited.size < maxFiles; depth++) {
    const next: string[] = [];
    for (const f of frontier.sort()) {
      const imps = (index.importsByFile.get(f) || []);
      const revs = (index.reverseImports.get(f) || []);
      for (const n of [...imps, ...revs].sort()) {
        if (!visited.has(n) && visited.size < maxFiles && fileAllowed(n)) {
          visited.add(n);
          next.push(n);
        }
      }
    }
    frontier = next;
  }

  // 5: assemble result. Files in BFS-visit order so the most-relevant come first.
  const files = [...visited];
  // Symbols: collect from those files, sorted by (score desc, file, line) so
  // the highest-relevance symbols come first.
  const symbolSet = new Set<string>();
  for (const s of seedSymbols) symbolSet.add(`${s.file}:${s.symbol}`);
  const symbols = [...symbolSet];
  return {
    files,
    symbols,
    target_symbol: scored[0] ? `${scored[0].file}:${scored[0].symbol}` : (files[0] || ""),
  };
}
